//! Known-answer tests: `tests/golden/rh_ids_v2.txt`, generated by the independent reference
//! implementation `bin/gen_rng_golden.py`, must be reproduced bit for bit (SPR-002 T-02..T-05;
//! V-DET-09 style golden vectors). Never edit the file by hand; regenerate it, and treat any
//! change to it as a C3 change.

#![allow(
    clippy::expect_used,
    reason = "test helpers: a missing or malformed golden file must fail the test loudly"
)]

use rand_chacha::ChaCha8Rng;
use rand_core::{Rng, SeedableRng};
use rh_ids::rng::{h64_bytes, h64_words, mix, tag};
use rh_ids::{
    BranchSalt, ForkPolicy, LightStream, PurposeId, RngKey, SaltLineage, SystemId, TimelineId, h,
};
use rh_ids::{PersonId, person};

const GOLDEN: &str = "tests/golden/rh_ids_v2.txt";

/// The golden lines whose first field is `kind`, split into fields (the kind dropped).
fn lines(kind: &str) -> Vec<Vec<String>> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(GOLDEN);
    let text = std::fs::read_to_string(&path).expect("golden file is readable");
    let rows: Vec<Vec<String>> = text
        .lines()
        .filter(|l| !l.starts_with('#'))
        .map(|l| l.split_whitespace().map(str::to_owned).collect::<Vec<_>>())
        .filter(|f| f.first().map(String::as_str) == Some(kind))
        .map(|f| f[1..].to_vec())
        .collect();
    assert!(!rows.is_empty(), "no `{kind}` lines in {GOLDEN}");
    rows
}

fn int<T: std::str::FromStr>(s: &str) -> T
where
    T::Err: std::fmt::Debug,
{
    s.parse().expect("golden integer")
}

fn hex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex"))
        .collect()
}

#[test]
fn chacha8_blocks_match_the_reference() {
    for f in lines("chacha8") {
        let key: [u8; 32] = hex(&f[0]).try_into().expect("32-byte key");
        let mut rng = ChaCha8Rng::from_seed(key);
        rng.set_stream(int(&f[2]));
        rng.set_word_pos(u128::from(int::<u64>(&f[1])) * 16);
        let mut block = [0_u8; 64];
        rng.fill_bytes(&mut block);
        assert_eq!(block.to_vec(), hex(&f[3]), "chacha8 line {f:?}");
    }
}

#[test]
fn h_matches_the_reference() {
    for f in lines("h") {
        let key = rng_key(&f);
        assert_eq!(h(&key, int(&f[7])), int::<u64>(&f[8]), "h line {f:?}");
    }
}

#[test]
fn splitmix_mix_matches_the_reference() {
    for f in lines("mix") {
        assert_eq!(mix(int(&f[0])), int::<u64>(&f[1]), "mix line {f:?}");
    }
}

#[test]
fn h64_words_matches_the_reference() {
    for f in lines("h64_words") {
        let n: usize = int(&f[1]);
        let words: Vec<u64> = f[2..2 + n].iter().map(|w| int(w)).collect();
        assert_eq!(
            h64_words(int(&f[0]), &words),
            int::<u64>(&f[2 + n]),
            "line {f:?}"
        );
    }
}

#[test]
fn tags_and_purpose_ids_match_the_reference() {
    for f in lines("tag") {
        let name = if f[0] == "-" { "" } else { f[0].as_str() };
        assert_eq!(tag(name), int::<u64>(&f[1]), "tag line {f:?}");
        assert_eq!(h64_bytes(0, name.as_bytes()), int::<u64>(&f[1]));
    }
    for f in lines("purpose") {
        assert_eq!(
            PurposeId::of(&f[0]).to_raw(),
            int::<u64>(&f[1]),
            "purpose line {f:?}"
        );
    }
}

#[test]
fn light_streams_match_the_reference() {
    for f in lines("light") {
        let key = rng_key(&f);
        assert_eq!(
            LightStream::new(&key).draw(int(&f[7])),
            int::<u64>(&f[8]),
            "light line {f:?}"
        );
    }
}

/// The seven key fields at the start of an `h` or `light` line.
fn rng_key(f: &[String]) -> RngKey {
    RngKey {
        world_seed: int(&f[0]),
        branch_salt: BranchSalt::from_raw(int(&f[1])),
        system: SystemId::from_raw(int(&f[2])),
        purpose: PurposeId::from_raw(int(&f[3])),
        entity: int(&f[4]),
        epoch: int(&f[5]),
        t: int(&f[6]),
    }
}

#[test]
fn branch_salts_match_the_reference() {
    for f in lines("salt") {
        let n: usize = int(&f[0]);
        let mut lineage = SaltLineage::canonical();
        for step in 0..n {
            let at: i64 = int(&f[1 + 2 * step]);
            let timeline = TimelineId::from_raw(int(&f[2 + 2 * step]));
            lineage = lineage
                .fork(at, timeline, ForkPolicy::ROLLOUT)
                .expect("valid lineage");
        }
        let t: i64 = int(&f[1 + 2 * n]);
        assert_eq!(
            lineage.branch_salt(t).to_raw(),
            int::<u64>(&f[2 + 2 * n]),
            "salt line {f:?}"
        );
    }
}

/// T-05: person identifiers are stable across runs and match the independent reference.
#[test]
fn person_ids_match_the_reference() {
    let id = |s: &String| PersonId::from_raw(int(s));
    for f in lines("founder") {
        assert_eq!(
            person::founder_base(int(&f[0]), int(&f[1])),
            id(&f[2]),
            "{f:?}"
        );
    }
    for f in lines("child") {
        assert_eq!(
            person::child_base(id(&f[0]), int(&f[1])),
            id(&f[2]),
            "{f:?}"
        );
    }
    for f in lines("immigrant") {
        let got = person::immigrant_base(int(&f[0]), int(&f[1]), int(&f[2]), int(&f[3]));
        assert_eq!(got, id(&f[4]), "{f:?}");
    }
    for f in lines("rehash") {
        assert_eq!(person::rehash(id(&f[0]), int(&f[1])), id(&f[2]), "{f:?}");
    }
}
